			lastDeployed: "abc123",
			current:      "abc123",
			force:        false,
			want:         true,
		},
		{
			name:         "same commit with force does not skip",
			lastDeployed: "abc123",
			current:      "abc123",
			force:        true,
			want:         false,
		},
		{
			name:         "different commit does not skip",
			lastDeployed: "abc123",
			current:      "def456",
			force:        false,
