			current:      "abc123",
			force:        false,
			want:         false,
		},
		{
			name:         "both empty without force skips",
			lastDeployed: "",
			current:      "",
			force:        false,
			want:         true,
		},
		{
			name:          "same commit with needsRedeploy does not skip",
			lastDeployed:  "abc123",
			current:       "abc123",
			needsRedeploy: true,
