func TestShouldTriggerCircuitBreaker(t *testing.T) {
	tests := []struct {
		name          string
		lastAttempted string
		current       string
		attempts      int
		maxAttempts   int
		force         bool
		want          bool
	}{
		{
			name:          "triggers at max attempts on same commit",
			lastAttempted: "abc123",
			current:       "abc123",
			attempts:      3,
			maxAttempts:   3,
			force:         false,
			want:          true,
		},
		{
			name:          "triggers above max attempts on same commit",
			lastAttempted: "abc123",
			current:       "abc123",
			attempts:      5,
			maxAttempts:   3,
			force:         false,
			want:          true,
		},
		{
			name:          "does not trigger below max attempts",
			lastAttempted: "abc123",
			current:       "abc123",
			attempts:      2,
			maxAttempts:   3,
			force:         false,
			want:          false,
		},
		{
			name:          "does not trigger on different commit",
			lastAttempted: "abc123",
			current:       "def456",
			attempts:      5,
			maxAttempts:   3,
			force:         false,
			want:          false,
		},
		{
			name:          "force overrides circuit breaker",
			lastAttempted: "abc123",
			current:       "abc123",
			attempts:      5,
			maxAttempts:   3,
			force:         true,
			want:          false,
		},
		{
			name:          "zero attempts never triggers",
			lastAttempted: "abc123",
			current:       "abc123",
			attempts:      0,
			maxAttempts:   3,
			force:         false,
			want:          false,
		},
		{
			name:          "empty last attempted does not trigger",
			lastAttempted: "",
			current:       "abc123",
			attempts:      5,
			maxAttempts:   3,
			force:         false,
			want:          false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := shouldTriggerCircuitBreaker(tt.lastAttempted, tt.current, tt.attempts, tt.maxAttempts, tt.force)
			assert.Equal(t, tt.want, got)
		})
	}
}

